PRAGMA foreign_keys = ON;
ALTER TABLE drill_unit_progress ADD COLUMN stage TEXT NOT NULL DEFAULT 'concept' CHECK (stage IN ('concept','example','easy','medium','complete'));
UPDATE drill_unit_progress SET stage=CASE WHEN status='complete' THEN 'complete' WHEN medium_completed>0 OR easy_completed>=easy_total THEN 'medium' WHEN easy_completed>0 THEN 'easy' ELSE 'concept' END;
PRAGMA optimize;
